// Código para n8n
function combinarSecciones(items) {
    // Estilos base
    const estilos = `
        <style>
            body {
                font-family: Arial, sans-serif;
                line-height: 1.6;
                color: #333;
                max-width: 800px;
                margin: 0 auto;
                padding: 20px;
            }
            .blog-section {
                margin-bottom: 3em;
                padding: 20px;
            }
            .section-title {
                font-size: 2em;
                color: #2c3e50;
                margin-bottom: 1em;
                font-weight: 700;
            }
            .subsection-title {
                font-size: 1.5em;
                color: #34495e;
                margin: 1.5em 0 1em;
                font-weight: 600;
            }
            .section-intro {
                font-size: 1.1em;
                color: #2c3e50;
                line-height: 1.8;
                margin-bottom: 1.5em;
            }
            .section-content {
                margin-bottom: 1.5em;
                line-height: 1.8;
            }
            .section-conclusion {
                font-style: italic;
                color: #2c3e50;
                margin-top: 2em;
                padding-top: 1em;
                border-top: 1px solid #eee;
            }
        </style>
    `;

    // Procesar los items
    const secciones = items[0].json.text;

    // Construir el HTML
    const htmlCompleto = `
        <!DOCTYPE html>
        <html lang="es">
        <head>
            <meta charset="UTF-8">
            <meta name="viewport" content="width=device-width, initial-scale=1.0">
            <title>Blog Post</title>
            ${estilos}
        </head>
        <body>
            <main class="blog-content">
                ${secciones.join('\n')}
            </main>
        </body>
        </html>
    `;

    // Retornar en el formato que espera n8n
    return [{
        json: {
            html: htmlCompleto
        }
    }];
}

// Retornar la función para n8n
return combinarSecciones(items);

function formatForGoogleDocs(items) {
    try {
        const contenidoOriginal = items[0].json.html || items[0].html || '';

        // Extraer el contenido del body usando regex
        const bodyContent = contenidoOriginal.match(/<main[^>]*>([\s\S]*?)<\/main>/i)?.[1] || contenidoOriginal;

        // Limpieza y simplificación del HTML
        let contenidoLimpio = bodyContent
            // Eliminar clases CSS
            .replace(/\sclass="[^"]*"/g, '')
            // Convertir article en div
            .replace(/<\/?article[^>]*>/g, '')
            // Limpiar espacios y líneas extra
            .replace(/\n\s+\n/g, '\n')
            .replace(/\n{3,}/g, '\n\n')
            .trim();

        // Aplicar estilos básicos compatibles con Google Docs
        contenidoLimpio = contenidoLimpio
            // Formatear títulos
            .replace(/<h2[^>]*>(.*?)<\/h2>/g, '<h2 style="font-size: 24px; color: #333; margin: 20px 0; border-bottom: 1px solid #eee; padding-bottom: 10px;">$1</h2>')
            // Formatear subtítulos
            .replace(/<h3[^>]*>(.*?)<\/h3>/g, '<h3 style="font-size: 20px; color: #444; margin: 15px 0;">$1</h3>')
            // Formatear párrafos
            .replace(/<p[^>]*>(.*?)<\/p>/g, '<p style="font-size: 14px; line-height: 1.6; margin: 10px 0; color: #333;">$1</p>');

        // Estructura final del documento
        const documentoFinal = `
<div style="font-family: Arial, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px;">
    ${contenidoLimpio}
</div>`;

        return [{
            json: {
                html: documentoFinal
            }
        }];
    } catch (error) {
        console.error('Error al procesar el documento:', error);
        return [{
            json: {
                html: '<p>Error al procesar el contenido</p>'
            }
        }];
    }
}

// Retornar la función para n8n
return formatForGoogleDocs(items);

